def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure there are at least 2 bytes to pop
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop 16-bit value")
    value_bytes = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(value_bytes, byteorder='big', signed=False)

