    if hasattr(self, "make_bins") and callable(self.make_bins):
        self.bins = self.make_bins()
    else:
        # If initial_value is a callable, call it
        if callable(getattr(self, "initial_value", None)):
            self.bins = self.initial_value()
        else:
            self.bins = getattr(self, "initial_value", None)

