def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration. Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    bins = np.asarray(bins, dtype=float)
    edges = np.asarray(edges, dtype=float)

    if edges.ndim != 1:
        raise ValueError("`edges` must be a 1‑D sequence of bin boundaries.")
    if bins.ndim != 1:
        raise ValueError("`bins` must be a 1‑D sequence of bin values.")
    if len(edges) != len(bins) + 1:
        raise ValueError("Length of `edges` must be one greater than length of `bins`.")

    widths = np.diff(edges)
    return np.sum(bins * widths)

