def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    from collections import Counter
    if not dicts:
        return {}
    counters = [Counter(d) for d in dicts]
    result = dict(reduce(operator.add, counters))
    return result

