import socket

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Direct checks for common local identifiers
    local_names = {"localhost", "127.0.0.1", "::1"}
    if host in local_names:
        return True

    try:
        # Resolve the host to all addresses and check each
        for result in socket.getaddrinfo(host, None):
            _, _, _, _, sockaddr = result
            ip = sockaddr[0]
            if ip in ("127.0.0.1", "::1"):
                return True
    except socket.gaierror:
        # Could not resolve, so treat as non-local
        return False

    return False

