def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    try:
        value = args["value"]
        min_ = args["min"]
        max_ = args["max"]
    except KeyError as exc:
        missing = exc.args[0]
        raise KeyError(f"Missing required argument: {missing}") from exc

    if min_ > max_:
        raise ValueError("minimum value cannot be greater than maximum")

    if not (min_ <= value <= max_):
        raise ValueError(
            f"value {value} is out of bounds [{min_}, {max_}]"
        )

    return value

